def pre(n):
    return 0 <= n <= 250

def post(n, result):
    # Independent check: a composite n <= 250 always has a divisor d with 2 <= d <= 15
    # (since 16*16 = 256 > 250), and d < n excludes n itself.
    has_divisor = False
    for d in range(2, 16):
        if d < n and n % d == 0:
            has_divisor = True
    expected = (n > 1) and (not has_divisor)
    return result == expected
